def remediated_cwe_094_dynamic_calculator(user_expression: str) -> Any:
    import ast
    import operator
    OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    def eval_node(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        elif isinstance(node, ast.BinOp) and type(node.op) in OPS:
            return OPS[type(node.op)](eval_node(node.left), eval_node(node.right))
        raise ValueError('Unsafe mathematical expression')
    parsed = ast.parse(user_expression, mode='eval')
    return eval_node(parsed.body)

def autonomous_agent_code_runner(llm_response_text: str):
    # CodeLens Guardrail: Strict AST static validation + isolated Docker container execution
    import ast
    tree = ast.parse(llm_response_text)
    # Disallow os, subprocess, network calls
    for node in ast.walk(tree):
        if isinstance(node, ast.Import) and any(alias.name in {'os', 'subprocess', 'sys'} for alias in node.names):
            raise PermissionError('Prohibited library import')
    # Route to isolated sandbox
    return run_in_ephemeral_docker_sandbox(llm_response_text)

def remediated_owasp_llm05_agent_terminal_executor(agent_action_payload: dict) -> str:
    import shlex
    ALLOWED_COMMANDS = {'git', 'pytest', 'ls', 'pwd', 'python'}
    raw_command = agent_action_payload.get('command', '')
    parsed_tokens = shlex.split(raw_command)
    if not parsed_tokens or parsed_tokens[0] not in ALLOWED_COMMANDS:
        raise PermissionError(f'Unauthorized command binary: {parsed_tokens[0] if parsed_tokens else "empty"}')
    res = subprocess.run(parsed_tokens, capture_output=True, text=True, check=True, timeout=10)
    return res.stdout

