function deepMerge(target, src) {
  for (const k in src) {
    if (typeof src[k] === 'object') target[k] = deepMerge(target[k]||{}, src[k]);
    else target[k] = src[k];
  }
  return target;
}
app.post('/config', (req,res)=>{ config = deepMerge(config, req.body); res.json(config); });

fixed_code:
function deepMerge(target, src) {
  for (const k of Object.keys(src)) {
    if (k === '__proto__' || k === 'constructor' || k === 'prototype') continue;
    if (src[k] && typeof src[k] === 'object' && !Array.isArray(src[k])) {
      target[k] = deepMerge(target[k] || {}, src[k]);
    } else target[k] = src[k];
  }
  return target;
}
app.post('/config', (req,res)=>{ config = deepMerge(config, req.body); res.json(config); });

