            column: z.enum(['email', 'name', 'status']),
            value: z.string().max(100)
        }),
        prompt: `Extract search parameters from: ${naturalLanguageQuery}`
    });

    try {
        // Execute parameterized query safely
        const results = await db.query(
            `SELECT id, name, email FROM users WHERE ${queryParams.column} = $1`,
            [queryParams.value]
        );
        return Response.json({ data: results });
    } catch (e) {
        return Response.json({ error: 'DB Error' }, { status: 500 });
    }
}

