import express, { Request, Response } from 'express';
import { execFile } from 'child_process';

const app = express();
app.use(express.json());

// [SANITIZER / FIX] - Allowlist of explicitly permitted diagnostic tools
const ALLOWED_COMMANDS = ['ping', 'traceroute']; 

app.post('/api/network-diag', async (req: Request, res: Response) => {
    // Request JSON structured output from LLM: { "tool": "ping", "target": "8.8.8.8" }
    const llmResponse = await askLLMStructured(req.body.issue);
    const { tool, target } = JSON.parse(llmResponse);

    if (!ALLOWED_COMMANDS.includes(tool)) {
        return res.status(403).json({ error: "Command not permitted." });
    }

    // Use execFile to prevent shell metacharacter injection via 'target'
    execFile(tool, ['-c', '4', target], (error, stdout, stderr) => {
        if (error) return res.status(500).json({ error: stderr });
        res.json({ output: stdout });
    });
});

