import { Request, Response, NextFunction } from 'express';

export function b2bOrder() {
  return ({ body }: Request, res: Response, next: NextFunction) => {
    // Safe remediation: Parse structured JSON array instead of executing dynamic code
    const orderLines = JSON.parse(body.orderLinesData || '[]');
    if (!Array.isArray(orderLines)) return res.status(400).json({ error: 'Invalid order structure' });
    res.json({ status: 'success', count: orderLines.length });
  };
}

