'use client';
import { useSearchParams } from 'next/navigation';
export default function Page() {
  const q = useSearchParams().get('expr') || '';
  // Secure: only run a safe arithmetic parser over a whitelist
  const result = safeEval(q);
  return <pre>{String(result)}</pre>;
}

function safeEval(expr: string): number | string {
  if (!/^[0-9+\-*/().\s]+$/.test(expr)) return 'invalid';
  try { return Function('"use strict";return (' + expr + ')')() as number; }
  catch { return 'invalid'; }
}

