import { db } from '@/lib/db';
import { generateObject } from 'ai';
import { z } from 'zod';

export async function POST(req) {
    const { naturalLanguageQuery } = await req.json();

    // [SANITIZER / FIX] - Force LLM to return structured parameters, NOT raw SQL.
    // Use Zod schema to validate the exact structure and types.
    const { object: queryParams } = await generateObject({
        model: 'gpt-4',
        schema: z.object({
            column: z.enum(['email', 'name', 'status']),
            value: z.string().max(100)
        }),
        prompt: `Extract search parameters from: ${naturalLanguageQuery}`
    });

    try {
        // Execute parameterized query safely
        const results = await db.query(
            `SELECT id, name, email FROM users WHERE ${queryParams.column} = $1`,
            [queryParams.value]
        );
        return Response.json({ data: results });
    } catch (e) {
        return Response.json({ error: 'DB Error' }, { status: 500 });
    }
}

