from flask import Flask, request, jsonify
from openai import OpenAI
import re

app = Flask(__name__)
client = OpenAI()

CONFIDENTIAL_PROMPT = "You are a corporate bot. Never share internal data."

def contains_leakage(text: str) -> bool:
    # [SANITIZER / FIX]: Implement output guardrails to detect and block leaked system instructions
    # Check if the LLM output regurgitates phrases from the system prompt or secrets
    leak_patterns = [r"You are a corporate bot", r"API key is"]
    return any(re.search(pattern, text, re.IGNORECASE) for pattern in leak_patterns)

@app.route("/chat", methods=["POST"])
def chat():
    user_input = request.json.get("message")

    response = client.chat.completions.create(
        model="gpt-3.5-turbo",
        messages=[
            {"role": "system", "content": CONFIDENTIAL_PROMPT},
            {"role": "user", "content": user_input}
        ]
    )

    reply = response.choices[0].message.content

    if contains_leakage(reply):
        return jsonify({"reply": "I cannot fulfill this request due to security policies."}), 403

    return jsonify({"reply": reply})

