# Safe remediation: assert parameter is primitive string and sanitize regex operators
from flask import Flask, request, jsonify
from pymongo import MongoClient

app = Flask(__name__)
client = MongoClient('mongodb://localhost:27017/')
db = client['app_db']

@app.route('/api/user/search', methods=['POST'])
def search_user():
    user_query = request.get_json() or {}
    username_input = user_query.get('username')
    if not isinstance(username_input, str):
        return jsonify({"error": "Invalid input type"}), 400
    # Safe: sanitized primitive string lookup
    result = db.users.find_one({"username": str(username_input)})
    if result:
        return jsonify({"found": True, "user_id": str(result['_id'])})
    return jsonify({"found": False}), 404

from flask import Flask, request
import sqlite3

app = Flask(__name__)

@app.route('/user')
def get_user():
    username = request.args.get('username', '')
    if not username:
        return 'missing username', 400
    conn = sqlite3.connect('app.db')
    cur = conn.cursor()
    # Secure: parameterized query
    cur.execute('SELECT id, name FROM users WHERE name = ?', (username,))
    return str(cur.fetchall())

