@app.post("/math_solver")
def solve_math(data: MathQuery):
    # LLM instructed to return Python code
    response = client.chat.completions.create(
        model="gpt-4",
        messages=[{"role": "system", "content": "Return ONLY valid python code to solve the math problem. No markdown."},
