import OpenAI from 'openai';

export async function renderMarkdownResponse(prompt: string): Promise<string> {
  const client = new OpenAI();
  const resp = await client.chat.completions.create({
    model: 'gpt-4o',
    messages: [{ role: 'user', content: prompt }]
  });
  const rawMarkdown: string = resp.choices[0].message.content ?? '';
  // VULNERABLE: Returned for dangerouslySetInnerHTML without HTML sanitization
  return `<div class='content'>${rawMarkdown}</div>`;
}

fixed_code:
import OpenAI from 'openai';
import DOMPurify from 'isomorphic-dompurify';

export async function renderMarkdownResponse(prompt: string): Promise<string> {
  const client = new OpenAI();
  const resp = await client.chat.completions.create({
    model: 'gpt-4o',
    messages: [{ role: 'user', content: prompt }]
  });
  const rawMarkdown: string = resp.choices[0].message.content ?? '';
  // FIXED: Sanitized with DOMPurify
  const clean = DOMPurify.sanitize(rawMarkdown);
  return `<div class='content'>${clean}</div>`;
}

original_code:
import OpenAI from 'openai';

export async function evaluateDynamicExpression(formulaPrompt: string): Promise<unknown> {
  const client = new OpenAI();
  const resp = await client.chat.completions.create({
    model: 'gpt-4o',
    messages: [{ role: 'user', content: `Generate a JS calculation function for: ${formulaPrompt}` }]
  });
  const jsCode: string = resp.choices[0].message.content ?? '';
  // VULNERABLE: Direct code execution of LLM output via new Function
  const dynamicFn = new Function(jsCode);
  return dynamicFn();
}

